"use strict";(self.webpackChunklifewell_docs=self.webpackChunklifewell_docs||[]).push([["6409"],{38839(e){e.exports=JSON.parse('{"tag":{"label":"concepts","permalink":"/es/tags/concepts","allTagsPath":"/es/tags","count":8,"items":[{"id":"concepts/appearance","title":"Apariencia","description":"Un icono y un panel para tema, color, redondez, densidad, tama\xf1o de texto, tipograf\xeda, superficies y movimiento. Todo se aplica antes de mostrar la p\xe1gina.","permalink":"/es/concepts/appearance"},{"id":"concepts/architecture","title":"Arquitectura","description":"Una aplicaci\xf3n est\xe1tica de p\xe1gina \xfanica sobre Postgres, con funciones perimetrales solo cuando el navegador no debe guardar algo. Qu\xe9 se ejecuta d\xf3nde y por qu\xe9 no hay servidor propio.","permalink":"/es/concepts/architecture"},{"id":"your-data/where-it-lives","title":"D\xf3nde viven tus datos","description":"Tus registros se guardan en una base de datos Postgres, tus fotos en tu Google Drive y, si activas el registro sin conexi\xf3n, algunas entradas r\xe1pidas pendientes en tu dispositivo.","permalink":"/es/your-data/where-it-lives"},{"id":"concepts/data-model","title":"El modelo de datos","description":"C\xf3mo guarda LifeWell una vida: una tabla por concepto, un almac\xe9n com\xfan para todos los seguimientos y tres decisiones que organizan lo dem\xe1s.","permalink":"/es/concepts/data-model"},{"id":"concepts/language-and-units","title":"Idioma y unidades","description":"LifeWell ofrece diez idiomas en la aplicaci\xf3n, la documentaci\xf3n y la extensi\xf3n para navegador. Tus unidades se eligen por separado.","permalink":"/es/concepts/language-and-units"},{"id":"domains/overview","title":"Las siete \xe1reas","description":"LifeWell organiza siete \xe1reas alrededor de ti: primero personas, despu\xe9s recuerdos, vida diaria y compartir; a su alrededor, salud, mente y etapas de la vida. Puedes ocultar seis sin borrar datos. Compartir permanece visible.","permalink":"/es/domains/overview"},{"id":"concepts/privacy-and-security","title":"Privacidad y seguridad","description":"Qu\xe9 sale de tu dispositivo y qu\xe9 no: acceso sin contrase\xf1a, reglas de base de datos por fila, an\xe1lisis sin datos personales, permiso de contactos, im\xe1genes de identificaciones y l\xedmites de lo que LifeWell afirma.","permalink":"/es/concepts/privacy-and-security"},{"id":"concepts/offline-and-sync","title":"Sin conexi\xf3n y sincronizaci\xf3n","description":"LifeWell pausa la aplicaci\xf3n cuando se pierde la conexi\xf3n y ofrece una opci\xf3n para guardar algunas entradas r\xe1pidas en este dispositivo hasta que vuelva.","permalink":"/es/concepts/offline-and-sync"}],"unlisted":false}}')}}]);